import{_ as a,o as e,c as i,a2 as n}from"./chunks/framework.Ddyno5UB.js";const k=JSON.parse('{"title":"Podman Transition","description":"","frontmatter":{},"headers":[],"relativePath":"containers/8-podman-transition.md","filePath":"containers/8-podman-transition.md"}'),t={name:"containers/8-podman-transition.md"};function o(r,s,l,d,h,p){return e(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="podman-transition" tabindex="-1">Podman Transition <a class="header-anchor" href="#podman-transition" aria-label="Permalink to &quot;Podman Transition&quot;">​</a></h1><p>Docker revolutionized the industry, but its architecture relies on a massive, highly privileged daemon process (<code>dockerd</code>) running as root. This is a single point of failure and a massive security risk in enterprise environments.</p><p>Enter <strong>Podman</strong> (Pod Manager), a drop-in replacement for Docker built by Red Hat.</p><h2 id="why-podman" tabindex="-1">Why Podman? <a class="header-anchor" href="#why-podman" aria-label="Permalink to &quot;Why Podman?&quot;">​</a></h2><p>Podman solves Docker&#39;s two biggest problems:</p><ol><li><strong>Daemonless Architecture:</strong> Podman does not have a background daemon. When you run a container, Podman creates a standard Linux child process. If the Podman CLI crashes, the container keeps running as an independent process managed by systemd.</li><li><strong>Rootless by Default:</strong> Podman is designed from the ground up to allow normal, unprivileged users to build and run containers. If a hacker escapes a rootless container, they pop out onto the host machine as a normal, powerless user (e.g., <code>sanjeev</code>).</li></ol><h2 id="the-alias-magic" tabindex="-1">The Alias Magic <a class="header-anchor" href="#the-alias-magic" aria-label="Permalink to &quot;The Alias Magic&quot;">​</a></h2><p>Because Podman aims to be a complete drop-in replacement for Docker, the CLI arguments are 100% identical.</p><p>Most developers simply set up a shell alias and never realize they aren&#39;t using Docker:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Add this to your ~/.bashrc or ~/.zshrc</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">alias</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> docker</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">podman</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># This actually runs &#39;podman ps&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span></span></code></pre></div><h2 id="systemd-integration-the-killer-feature" tabindex="-1">Systemd Integration (The Killer Feature) <a class="header-anchor" href="#systemd-integration-the-killer-feature" aria-label="Permalink to &quot;Systemd Integration (The Killer Feature)&quot;">​</a></h2><p>Because Docker relies on its own daemon to manage containers, integrating Docker containers with native Linux tools like <code>systemd</code> (to start containers on server boot) is notoriously difficult.</p><p>Because Podman doesn&#39;t have a daemon, it natively relies on <code>systemd</code> to manage container lifecycles in production!</p><p>Podman can automatically generate native <code>systemd</code> <code>.service</code> files for your running containers.</p><h3 id="generating-a-systemd-service" tabindex="-1">Generating a Systemd Service <a class="header-anchor" href="#generating-a-systemd-service" aria-label="Permalink to &quot;Generating a Systemd Service&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Run a container normally</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">podman</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx:latest</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Tell Podman to generate a systemd unit file for it</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">podman</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> generate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-web</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --files</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. Move the generated file to the systemd directory</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> container-my-web.service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/systemd/system/</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 4. Enable it to start on boot!</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --now</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> container-my-web</span></span></code></pre></div><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>In newer versions of Podman, <code>podman generate systemd</code> is being deprecated in favor of <strong>Quadlets</strong>, which allow you to write a <code>.container</code> file natively inside systemd directories that Podman automatically parses.</p></div>`,17)])])}const m=a(t,[["render",o]]);export{k as __pageData,m as default};
